    const error = new URLSearchParams(location.hash.split('?')[1] || '').get('error'); if (error) $('#account-form-error').textContent = error === 'google_unavailable' ? 'Google sign-in has not been configured yet.' : 'Google sign-in could not be completed. Try again or use email.';
